def replace_saved(roots, *, initial_samples_only=False, bounded_lead_blend=False,
                  reconcile_builder_sources=False, batch_guides=False,direct_corner_source=False,
                  cycle_cores=False,ordinary_core_repair=False,strip_refinement=False,
                  radial_edge_budget=6.5,refinement_limit=7.,guide_chord_blend=0.,
                  corner_contact_retry=False,guarded_guide_retry=False,capped_profile=False,core_homotopy=False,
                  multisite_weighted_grading=False,contact_identity_fallback=False,minimum_profile_depth=0.,profile_slope_reserve=0.):
    """Copy caller paths once, retaining shared roots and original fallback data.

    This operates on the framed patch call, so neither the complete provider's
    transport contract nor its source-object intake is replaced. Existing recipe
    markers reject accidental double application. Input nodes are not edited.
    Optional builder-source reconciliation transfers canonical entry-point names
    to copied groups; use it in a disposable export session, never a live scene.
    """
    single = not isinstance(roots, (list, tuple))
    source = [roots] if single else list(roots)
    memo, certificates = {}, []
    visiting = set()

    def visit(tree):
        if tree in memo:
            return memo[tree]
        if tree in visiting:
            raise ValueError('Cycle in constructor calls or builder provenance: '+tree.name)
        visiting.add(tree)
        if tree.get('st_corner_pattern_recipe'):
            raise ValueError('Corner-pattern recipe already applied: '+tree.name)
        if family(tree):
            result, certificate = build(tree, initial_samples_only=initial_samples_only,
                                        bounded_lead_blend=bounded_lead_blend,batch_guides=batch_guides,
                                        direct_corner_source=direct_corner_source, cycle_cores=cycle_cores,
                                        ordinary_core_repair=ordinary_core_repair,strip_refinement=strip_refinement,
                                        radial_edge_budget=radial_edge_budget,refinement_limit=refinement_limit,
                                        guide_chord_blend=guide_chord_blend,corner_contact_retry=corner_contact_retry,
                                        guarded_guide_retry=guarded_guide_retry,capped_profile=capped_profile,
                                        core_homotopy=core_homotopy,multisite_weighted_grading=multisite_weighted_grading,
                                        contact_identity_fallback=contact_identity_fallback,
                                        minimum_profile_depth=minimum_profile_depth,profile_slope_reserve=profile_slope_reserve)
            certificates.append(certificate)
        else:
            children = [(node.name, visit(node.node_tree)) for node in tree.nodes
                        if node.type == 'GROUP' and node.node_tree]
            changed = [(name, child) for name, child in children if child != tree.nodes[name].node_tree]
            # The dispatch builder retains its canonical entry point through
            # an ID property. Reconcile that non-evaluated dependency through
            # the same memo, so it reuses these recipes rather than exporting
            # a second set of superseded boundary/frame groups.
            source = tree.get('st_complete_constructor_source') if reconcile_builder_sources else None
            if source is not None and not isinstance(source, bpy.types.NodeTree):
                raise ValueError('Unexpected constructor provenance: '+tree.name)
            reconciled = visit(source) if source is not None else None
            source_changed = source is not None and reconciled != source
            result = tree.copy() if changed or source_changed else tree
            for name, child in changed:
                assign_group(result.nodes[name], child)
            if source_changed:
                result['st_complete_constructor_source'] = reconciled
        memo[tree] = result
        visiting.remove(tree)
        return result

    results = [visit(tree) for tree in source]
    if not certificates:
        raise ValueError('No supported framed patches in the supplied asset roots')
    if reconcile_builder_sources:
        # These two entry-point forms are addressed by patch.build() and
        # internal.extend(). Preserve their canonical names and interfaces;
        # loaded originals remain in memory but are not export dependencies.
        entries = [(old.name, old, new) for old, new in memo.items() if old != new
                   and old.name.startswith('Prochitecture Streets / Cached original patch owner v2')]
        if not entries:
            raise ValueError('No canonical constructor entry points were reconciled')
        for name, old, new in entries:
            old.name = 'Prochitecture Streets / Before recipe builder source / '+hashlib.sha256(name.encode()).hexdigest()[:16]
            new.name = name
            if new.name != name:
                raise ValueError('Could not preserve canonical constructor name: '+name)
        certificates[0]['reconciled_builder_entry_points'] = [name for name, _, _ in entries]
    return (results[0] if single else results), certificates
